for line in B.strip().split('\n'):
    for e in line.split(';'):
        if '=' in e:
            k,v=e.split('=',1); ALIAS.setdefault(k.strip(),[])
            for x in v.split(','):
                x=x.strip()
                if x and x not in ALIAS[k.strip()]: ALIAS[k.strip()].append(x)
